const std = @import("std");

pub fn main() void {
    // Array of numbers
    var numbers = [_]i64{12, 45, 7, 89, 23, 56};

    // Find the largest number
    var max: i64 = numbers[0];
    for (numbers[1..]) |num| {
        if (num > max) {
            max = num;
        }
    }

    // Print each value on its own line
    for (numbers) |num| {
        std.debug.print("{d}\n", .{num});
    }
}
