pub fn main() void {
    var i: i64 = 1;
    while (i <= 15) {
        if (i % 3 == 0 and i % 5 == 0) {
            std.debug.print("FizzBuzz\n", .{i});
        } else if (i % 3 == 0) {
            std.debug.print("Fizz\n", .{i});
        } else if (i % 5 == 0) {
            std.debug.print("Buzz\n", .{i});
        } else {
            std.debug.print("{d}\n", .{i});
        }
        i += 1;
    }
}
